const req = $input.first().json;
const SYSTEM = 'Eres el Agente Phy de la agencia Phygital, especializada en infraestructura phygital: e-commerce Next.js con stock híbrido Prisma, automatización con IA en n8n, agentes RAG para WhatsApp/Instagram, performance con Meta CAPI server-side y IoT/domótica. Responde en español, de forma cercana y conversacional, en máximo 3 frases. Si el usuario quiere contacto real, deriva al WhatsApp https://wa.me/56941539918 o al formulario del sitio.';
const history = Array.isArray(req.history) ? req.history.map(h => ({
  role: h.role === 'model' ? 'model' : 'user',
  parts: [{ text: String(h.text || '') }]
})) : [];
const contents = [...history, { role: 'user', parts: [{ text: String(req.message || '') }] }];
return [{ json: { systemInstruction: { parts: [{ text: SYSTEM }] }, contents } }];

const data = $input.first().json;
const text = data?.candidates?.[0]?.content?.parts?.[0]?.text || 'No pude generar una respuesta.';
return [{ json: { reply: text.trim() } }];
